//! 📥️ Actual additional host input stays beside its original consuming receiving source on cancellation.
use super::*;
use semio_framework_value::{retirement::controlled::ControlledRetirement,ErasedSnapshotRetirement,RetainedCloneGrant};
#[test]
fn original_host_scope_splits_readonly_measurement_from_the_same_unique_native_control(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📥️input/🔣️.json")).unwrap();let case=&fixture["checkpointProjection"];let mut observer=|_:NativeEncodeProgress|true;let mut identity=EntityIdentityAuthority::new(case["originalMaximumBytes"].as_u64().unwrap()as usize,&mut observer).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);receiver.begin().unwrap();
 let(result,allocated,released)=crate::test_allocation::observe_backing(||receiver.with_host_io(|scope|{scope.control().charge(case["hostCharge"].as_u64().unwrap()as usize)?;let original=scope.control()as*mut NativeEncodeControl<'_>;scope.with_projected_host_charge(case["proposedCharge"].as_u64().unwrap()as usize,|view,control|{assert_eq!(view.retirement,case["projectedRetirement"].as_u64().unwrap()as usize);assert_eq!(control as*mut NativeEncodeControl<'_>,original);control.charge(case["splitAdditionalCharge"].as_u64().unwrap()as usize)?;Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"same original projection write refused after actual admission"))})}));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);assert_eq!((allocated,released),(0,0));let receipt=receiver.pause();let actual=case["actualRetirement"].as_u64().unwrap()as usize+case["splitAdditionalCharge"].as_u64().unwrap()as usize;assert_eq!(receipt.received_retirement,actual);assert_eq!(receipt.source_owned(),Some(actual));let mut receiver=OriginalOperationReceiver::resume(receipt,&mut identity).unwrap();receiver.finish(0).unwrap();receiver.ensure_finished().unwrap();println!("[DEBUG] split readonly checkpoint projection shares original native control, actual charge settles after scalar refusal with zero allocations and no replacement authority");
}
#[test]
fn original_host_scope_projects_borrowed_framing_and_settles_only_actual_charge(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📥️input/🔣️.json")).unwrap();let case=&fixture["checkpointProjection"];let mut observer=|_:NativeEncodeProgress|true;let mut identity=EntityIdentityAuthority::new(case["originalMaximumBytes"].as_u64().unwrap()as usize,&mut observer).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);receiver.begin().unwrap();
 let result:Result<(),ValueError>=receiver.with_host_io(|scope|{scope.control().charge(case["hostCharge"].as_u64().unwrap()as usize)?;let(view,allocated,released)=crate::test_allocation::observe_backing(||scope.project_host_charge(case["proposedCharge"].as_u64().unwrap()as usize));assert_eq!((allocated,released),(0,0));let scalar=serde_json::to_value(view.unwrap()).unwrap();assert_eq!(scalar["received_retirement"],case["projectedRetirement"]);Err(ValueError::literal(ValueRefusalKind::InvalidValue,"actual host scope refused after admission"))});assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);let receipt=receiver.pause();assert_eq!(receipt.received_retirement,case["actualRetirement"].as_u64().unwrap()as usize);assert_eq!(receipt.source_owned(),Some(case["actualRetirement"].as_u64().unwrap()as usize));let mut receiver=OriginalOperationReceiver::resume(receipt,&mut identity).unwrap();receiver.finish(0).unwrap();receiver.ensure_finished().unwrap();println!("[DEBUG] original borrowed host scope projected10 allocated0 released0, refused actual3 resumes same source4096");
}
#[test]
fn original_operation_receiving_input_retains_partial_backing_and_same_source_receipt(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📥️input/🔣️.json")).unwrap();let cancelled=std::cell::Cell::new(false);let mut observer=|_:NativeEncodeProgress|!cancelled.get();let mut identity=EntityIdentityAuthority::new(fixture["maximum"].as_u64().unwrap()as usize,&mut observer).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);assert_eq!(receiver.begin().unwrap(),64);let mut partial=None;
 let (denied,births,releases)=crate::test_allocation::observe_backing(||receiver.encode_input(|control|{let mut bytes=control.allocate_vec::<u8>(4)?;bytes.extend_from_slice(b"ab");partial=Some(bytes);cancelled.set(true);control.checkpoint()}));assert_eq!(denied.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(births,4);assert_eq!(releases,0);assert_eq!(partial.as_ref().unwrap().as_slice(),b"ab");cancelled.set(false);receiver.finish(0).unwrap();let receipt=receiver.pause();assert_eq!(receipt.received_input,4);assert_eq!(receipt.source_owned(),Some(4));let mut receiver=OriginalOperationReceiver::resume(receipt,&mut identity).unwrap();receiver.continue_receiving_phase().unwrap();let (next,births,releases)=crate::test_allocation::observe_backing(||receiver.encode_input(|control|{let mut bytes=control.allocate_vec::<u8>(3)?;bytes.extend_from_slice(b"new");Ok(bytes)}));assert_eq!(births,3);assert_eq!(releases,0);let next=next.unwrap();receiver.finish(0).unwrap();let receipt=receiver.pause();assert_eq!(receipt.received_input,fixture["receivedInput"].as_u64().unwrap()as usize);assert_eq!(receipt.received_output,0);assert_eq!(receipt.source_owned(),Some(fixture["sourceOwned"].as_u64().unwrap()as usize));assert_eq!(identity.encode(|control|Ok::<_,ValueError>(control.owned_bytes())).unwrap(),7);drop(identity.pause().unwrap());
 for bytes in [partial.take().unwrap(),next]{let mut owner=ControlledRetirement::new(bytes).unwrap_or_else(|_|panic!("authored Vec input retirement failed"));let mut policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:4096,maximum_release_bytes:0,maximum_depth:32};let (_,_,denied_release)=crate::test_allocation::observe_backing(||owner.step(policy));assert_eq!(denied_release,0);policy.maximum_release_bytes=4096;while !owner.terminal_is_empty(){let (step,allocated,released)=crate::test_allocation::observe_backing(||owner.step(policy));let progress=step.unwrap().progress();assert!(progress.fits(policy));assert_eq!(allocated,progress.retained_capacity_bytes);assert_eq!(released,progress.released_bytes);}let (_,_,terminal_release)=crate::test_allocation::observe_backing(||drop(owner));assert_eq!(terminal_release,0);}
 eprintln!("[DEBUG] original same-phase input owns partial4 plus resumed3, keeps source7 maximum64 and releases actual backing only under original grant");
}

#[test]
fn original_operation_receiving_input_retirement_frame_preserves_distinct_source_ledger(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/♻️host/🔣️.json")).unwrap();let mut observer=|_:NativeEncodeProgress|true;let mut identity=EntityIdentityAuthority::new(fixture["maximum"].as_u64().unwrap()as usize,&mut observer).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);receiver.begin().unwrap();let bytes=receiver.encode_input(|control|{let mut bytes=control.allocate_vec::<u8>(8)?;bytes.extend_from_slice(b"snapshot");Ok(bytes)}).unwrap();receiver.finish(0).unwrap();let mut owner=ControlledRetirement::new(bytes).unwrap_or_else(|_|panic!("authored host backing retirement failed"));let denied=RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let (step,allocated,released)=crate::test_allocation::observe_backing(||owner.step(denied));assert_eq!(step.unwrap().progress(),Default::default());assert_eq!((allocated,released),(0,0));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:32};let mut capacity=0;let mut released_total=0;
 while !owner.terminal_is_empty(){let demand=owner.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();let(step,allocated,released)=crate::test_allocation::observe_backing(||receiver.retire_host(|control|{control.charge(demand)?;owner.step(grant)}));let progress=step.unwrap().progress();assert!(progress.fits(grant));assert_eq!(allocated,progress.retained_capacity_bytes);assert_eq!(released,progress.released_bytes);assert_eq!(demand,allocated);capacity+=allocated;released_total+=released;let receipt=receiver.pause();assert_eq!(receipt.received_input,8);assert_eq!(receipt.received_output,0);assert_eq!(receipt.received_retirement,capacity);assert_eq!(receipt.source_owned(),Some(8+capacity));assert!(receipt.finished);receiver=OriginalOperationReceiver::resume(receipt,&mut identity).unwrap();}
 assert!(capacity>0);assert!(released_total>=8);receiver.ensure_finished().unwrap();let receipt=receiver.pause();let canonical=serde_json::to_value(&receipt).unwrap();assert_eq!(canonical["received_retirement"].as_u64(),Some(capacity as u64));let (_,_,released)=crate::test_allocation::observe_backing(||drop(owner));assert_eq!(released,0);assert_eq!(identity.encode(|control|Ok::<_,ValueError>(control.owned_bytes())).unwrap(),8+capacity);eprintln!("[DEBUG] original host retirement frame source input8 capacity{} release{} remains finished and resumable",capacity,released_total);
}
#[test]
fn original_checkpoint_projection_is_measurement_only_and_refusal_settles_actual_ledger(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📥️input/🔣️.json")).unwrap();let case=&fixture["checkpointProjection"];
 let mut original_observer=|_:NativeEncodeProgress|true;let mut identity=EntityIdentityAuthority::new(case["originalMaximumBytes"].as_u64().unwrap()as usize,&mut original_observer).unwrap();let mut receiver=OriginalOperationReceiver::new(&mut identity);receiver.begin().unwrap();
 let result:Result<(),ValueError>=receiver.retire_host(|control|{control.charge(case["hostCharge"].as_u64().unwrap()as usize)?;Err(ValueError::literal(ValueRefusalKind::InvalidValue,"actual refused checkpoint stage"))});assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);
 let receipt=receiver.pause();let(view,allocated,released)=crate::test_allocation::observe_backing(||receipt.project_retirement_charge(case["proposedCharge"].as_u64().unwrap()as usize));let view=view.unwrap();assert_eq!((allocated,released),(0,0));let scalar=serde_json::to_value(&view).unwrap();assert_eq!(scalar["received_retirement"],case["projectedRetirement"]);assert!(serde_json::from_value::<OriginalOperationReceipt>(scalar).is_err());assert_eq!(receipt.received_retirement,case["actualRetirement"].as_u64().unwrap()as usize);assert_eq!(receipt.source_owned(),Some(case["actualRetirement"].as_u64().unwrap()as usize));let scalar=serde_json::to_value(&receipt).unwrap();assert_eq!(scalar["received_retirement"],case["actualRetirement"]);let mut receiver=OriginalOperationReceiver::resume(receipt,&mut identity).unwrap();receiver.finish(0).unwrap();let receipt=receiver.pause();assert!(receipt.finished);assert_eq!(identity.encode(|control|Ok::<_,ValueError>(control.owned_bytes())).unwrap(),case["actualRetirement"].as_u64().unwrap()as usize);
}
